/* Focused workspace, reporting and field workflow. All figures come from local records. */
const nf=n=>Number(n).toLocaleString('ar-SA');
let reportKind='variance',reportQuery='',reportState='all',reportBranch='all',reportPage=1;
function scopedRecords(){const ids=new Set(visibleOps().map(o=>o.id));return logs().filter(l=>ids.has(l.op))}
function operationSummary(o){const rows=results(o.id),ls=logs(o.id),counted=new Set(ls.map(l=>l.barcode));const reference=rows.filter(r=>r.expected!==null),done=reference.filter(r=>counted.has(r.barcode)).length;return {rows,ls,counted,done,total:o.ref.length,percent:o.ref.length?Math.round(done/o.ref.length*100):null,units:ls.reduce((s,l)=>s+l.qty,0),shortage:reference.reduce((s,r)=>s+Math.max(0,-r.diff),0),surplus:reference.reduce((s,r)=>s+Math.max(0,r.diff),0),unseen:reference.filter(r=>!counted.has(r.barcode)).length,matched:reference.filter(r=>counted.has(r.barcode)&&r.diff===0).length,pending:groups().filter(([k,ls])=>ls[0].op===o.id&&!db.resolutions[k]).length}}
function metric(label,value,detail,tone=''){return `<article class="w-metric ${tone}"><span>${label}</span><strong>${nf(value)}</strong><small>${detail}</small></article>`}
function workspaceBanner(){return `<div class="w-local"><i></i> مساحة تجريبية <span>الحفظ على هذا المتصفح · المزامنة بين الأجهزة غير متصلة</span></div>`}
function wOperationCard(o){const s=operationSummary(o);return `<article class="w-operation"><div class="w-op-title"><span class="w-op-icon">${icon('operations')}</span><div><h3>${esc(o.name)}</h3><small>${esc(o.branch)} · ${esc(o.id)}</small></div>${badges(o.status)}</div><div class="w-op-meta"><span>${o.type==='open'?'جرد حر':o.blind?'جرد بمرجع · أعمى':'جرد بمرجع'}</span><span>${o.staff.length} موظفين · ${nf(s.units)} وحدة</span></div>${s.percent===null?'<p class="w-open-note">جرد حر — لا توجد قائمة مرجعية لقياس نسبة الاكتمال</p>':`<div class="w-progress-label"><span>أصناف مرجعية جرى عدّها ${nf(s.done)} / ${nf(s.total)}</span><b>${nf(s.percent)}%</b></div><div class="w-progress"><i style="width:${s.percent}%"></i></div>`}<div class="w-op-footer"><span class="${s.pending?'w-attention':''}">${s.pending?nf(s.pending)+' تكرار يحتاج مراجعة':'لا توجد تكرارات معلقة'}</span><button onclick="detail('${o.id}')">فتح العملية ${icon('arrow')}</button></div></article>`}
dashboard=function(){const os=visibleOps(),ls=scopedRecords(),pending=groups().filter(([k])=>!db.resolutions[k]),refs=os.filter(o=>o.type==='reference').map(operationSummary),total=refs.reduce((s,r)=>s+r.total,0),done=refs.reduce((s,r)=>s+r.done,0);return workspaceBanner()+head(canManage()?'لوحة الشركة':'متابعة عمليات الفرع','أين وصل الجرد؟ وما الذي يحتاج قرارك الآن؟',`<button onclick="go('reports')">${icon('reports')} مركز التقارير</button>${canManage()?newButton():''}`)+`<div class="w-metrics">${metric('عمليات قيد التنفيذ',os.filter(o=>o.status==='open').length,'من '+nf(os.length)+' عمليات مسندة')}${metric('الأصناف المرجعية المعدودة',done,'من '+nf(total)+' صنف ضمن العمليات بمرجع')}${metric('الوحدات المسجلة',ls.reduce((s,l)=>s+l.qty,0),nf(ls.length)+' إدخالات جرد')}${metric('تكرارات تنتظر القرار',pending.length,'في الصنف والموقع والعملية نفسها',pending.length?'amber':'')}</div><div class="w-dashboard-grid"><section><div class="w-section-head"><div><h2>عملياتك الحالية</h2><p>افتح العملية لمتابعة الأصناف والفريق والنتائج.</p></div><button onclick="go('operations')">كل العمليات</button></div><div class="w-operation-grid">${os.filter(o=>o.status==='open').map(wOperationCard).join('')||'<div class="empty panel">لا توجد عمليات مفتوحة. أنشئ عملية وعيّن فريقك للبدء.</div>'}</div><section class="panel w-team"><div class="panel-title"><h2>إنجاز الموظفين</h2><button onclick="openReportKind('employees')">التقرير التفصيلي</button></div>${employeeRows(os).map(r=>`<div class="w-person"><i>${esc(r.name[0])}</i><div><b>${esc(r.name)}</b><small>${nf(r.records)} إدخالات · ${nf(r.items)} أصناف مختلفة</small></div><strong>${nf(r.units)} <small>وحدة</small></strong></div>`).join('')||'<div class="empty">لا يوجد موظفون مسندون بعد</div>'}</section></section><section class="w-side"><div class="panel w-next"><span class="w-eyebrow">الخطوة التالية</span><h2>${pending.length?'راجع التكرارات قبل الاعتماد':'جهّز فريقك للجرد'}</h2><p>${pending.length?'هناك إدخالات للصنف نفسه في الموقع نفسه. راجعها قبل إغلاق العملية.':'اختر الفرع والمسؤول والموظفين، ثم اسمح للفريق بالبدء.'}</p><button class="primary wide" onclick="go('${pending.length?'review':'operations'}')">${pending.length?'فتح قائمة المراجعة':'إدارة عمليات الجرد'} ${icon('arrow')}</button></div>${canManage()?`<div class="panel w-credit"><span>رصيد العمليات</span><strong>${operationBalance()===null?'غير محدد':nf(operationBalance())}</strong><p>${operationBalance()===null?'حدد حدود الباقة من إدارة المنصة.':'عمليات متاحة للإنشاء. الإغلاق لا يعيد الرصيد.'}</p><button onclick="go('addons')">شراء عمليات إضافية</button><small>عملية 50 ر.س · عمليتان 70 ر.س</small></div><div class="panel w-tools"><h3>إدارة الشركة</h3><button onclick="go('team')">${icon('team')} الموظفون والفروع</button><button onclick="openQuickEdit()">${icon('scan')} تعديل كمية بالباركود</button><button onclick="companyBranding()">${icon('settings')} هوية الشركة والتقارير</button></div>`:''}<div class="panel w-activity"><h3>آخر الإجراءات</h3>${db.audit.slice(0,4).map(a=>`<p>${esc(a.text)}<small>${new Date(a.time).toLocaleString('ar-SA')}</small></p>`).join('')||'<p>لا توجد إجراءات مسجلة حتى الآن.</p>'}</div></section></div>`};
function employeeRows(os=visibleOps()){const ids=new Set(os.map(o=>o.id)),ls=logs().filter(l=>ids.has(l.op));return db.users.filter(u=>u.role==='employee'&&os.some(o=>o.staff.includes(u.id))).map(u=>{const entries=ls.filter(l=>l.user===u.id);return {name:u.name,records:entries.length,items:new Set(entries.map(l=>l.barcode)).size,units:entries.reduce((s,l)=>s+l.qty,0),last:entries.map(l=>l.time).sort().at(-1)||null}}).sort((a,b)=>b.units-a.units)}
function reportData(){const o=op(selected);if(!o||!visibleOps().includes(o))return [];let rows=results(o.id),counted=new Set(logs(o.id).map(l=>l.barcode));rows=rows.filter(r=>{const q=reportQuery.trim().toLowerCase(),search=(r.barcode+' '+r.name).toLowerCase().includes(q);return search&&(reportState==='all'||reportState==='shortage'&&r.diff!==null&&r.diff<0||reportState==='surplus'&&r.diff!==null&&r.diff>0||reportState==='matched'&&r.diff===0&&counted.has(r.barcode)||reportState==='unseen'&&r.expected!==null&&!counted.has(r.barcode)||reportState==='unexpected'&&r.expected===null)});return rows}
function rowStatus(r,id=selected){if(r.expected===null)return ['بلا مرجع','neutral'];if(!logs(id).some(l=>l.barcode===r.barcode))return ['لم يُعدّ','unseen'];if(r.diff<0)return ['عجز','negative'];if(r.diff>0)return ['زيادة','positive'];return ['مطابق','matched']}
function reportTable(rows){return `<div class="table-wrap"><table class="w-report-table"><thead><tr><th>الصنف والباركود</th><th>المرجع</th><th>المعدود</th><th>الفرق</th><th>الحالة</th></tr></thead><tbody>${rows.map(r=>{const [title,tone]=rowStatus(r);return `<tr><td><b>${esc(r.name)}</b><small dir="ltr">${esc(r.barcode)}</small></td><td>${r.expected===null?'—':nf(r.expected)}</td><td>${nf(r.count)}</td><td class="${tone}" dir="ltr">${r.diff===null?'—':r.diff>0?'+'+r.diff:r.diff}</td><td><span class="w-status ${tone}">${title}</span></td></tr>`}).join('')||'<tr><td colspan="5" class="empty">لا توجد نتائج تطابق الفلاتر الحالية.</td></tr>'}</tbody></table></div>`}
function changeReportKind(kind){reportKind=kind;reportPage=1;render()}
function openReportKind(kind){reportKind=kind;go('reports')}
function chooseReportOperation(id){selected=id;reportState='all';reportQuery='';reportPage=1;render()}
function reportBody(){const o=op(selected);if(!o)return '<div class="empty">لا توجد عملية متاحة في هذا الفرع.</div>';if(reportKind==='employees')return `<div class="table-wrap"><table><thead><tr><th>الموظف</th><th>الإدخالات</th><th>الأصناف المختلفة</th><th>الوحدات</th><th>آخر إدخال</th></tr></thead><tbody>${employeeRows([o]).map(r=>`<tr><td>${esc(r.name)}</td><td>${nf(r.records)}</td><td>${nf(r.items)}</td><td>${nf(r.units)}</td><td>${r.last?new Date(r.last).toLocaleString('ar-SA'):'لم يبدأ'}</td></tr>`).join('')}</tbody></table></div>`;if(reportKind==='history')return `<div class="table-wrap"><table><thead><tr><th>الباركود</th><th>الموظف / المصدر</th><th>الموقع</th><th>الكمية</th><th>الحالة</th><th>الوقت</th></tr></thead><tbody>${db.logs.filter(l=>l.op===o.id).slice().reverse().map(l=>`<tr><td dir="ltr">${esc(l.barcode)}</td><td>${esc(l.user==='company'?'حساب الشركة':user(l.user))}<small>${l.source==='correction'?'تصحيح إداري':esc(l.note||'عدّ')}</small></td><td>${esc(l.location)}</td><td>${nf(l.qty)}</td><td>${l.excluded?'مستبعد مع حفظ الأثر':'معتمد في الإجمالي'}</td><td>${new Date(l.time).toLocaleString('ar-SA')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">لم يسجل الفريق أي إدخال بعد</td></tr>'}</tbody></table></div>`;const rows=reportData(),pages=Math.max(1,Math.ceil(rows.length/25));reportPage=Math.min(reportPage,pages);return reportTable(rows.slice((reportPage-1)*25,reportPage*25))+`<div class="w-pagination"><span>${nf(rows.length)} أصناف · صفحة ${nf(reportPage)} من ${nf(pages)}</span><div><button ${reportPage===1?'disabled':''} onclick="reportPage--;refreshReportResults()">السابق</button><button ${reportPage===pages?'disabled':''} onclick="reportPage++;refreshReportResults()">التالي</button></div></div>`}
function refreshReportResults(){const el=$('#wReportResults');if(el)el.innerHTML=reportBody()}
reports=function(){let os=visibleOps().filter(o=>reportBranch==='all'||o.branch===reportBranch);if(!os.some(o=>o.id===selected))selected=os[0]?.id;const o=op(selected),s=o?operationSummary(o):null;return workspaceBanner()+head('مركز التقارير','افهم النتيجة، حدّد الفروقات، ثم صدّر التقرير الذي تحتاجه.',`<button onclick="exportWorkspaceReport()">${icon('reports')} تصدير CSV</button>${featureButton('pdf','PDF',"printWorkspaceReport()")}${featureButton('word','Word',"wordWorkspaceReport()")}`)+`<section class="panel w-report-select"><label>الفرع<select aria-label="فرع التقرير" onchange="reportBranch=this.value;reportPage=1;render()"><option value="all">كل الفروع</option>${[...new Set(visibleOps().map(o=>o.branch))].map(b=>`<option value="${esc(b)}" ${b===reportBranch?'selected':''}>${esc(b)}</option>`).join('')}</select></label><label>عملية الجرد<select aria-label="عملية التقرير" onchange="chooseReportOperation(this.value)">${os.map(o=>`<option value="${o.id}" ${selected===o.id?'selected':''}>${esc(o.name)}</option>`).join('')}</select></label><div>${o?badges(o.status):''}<small>${o?esc(o.type==='open'?'جرد حر — الفروقات غير متاحة دون مرجع':'جرد بمرجع — الفروقات محسوبة من الكميات المسجلة'):'اختر عملية لعرض التقرير'}</small></div></section>${s?`<div class="w-metrics">${metric('الوحدات المعدودة',s.units,nf(s.ls.length)+' إدخالات')}${metric('العجز بالوحدات',s.shortage,o.type==='open'?'لا يوجد مرجع للمقارنة':'يشمل الأصناف التي لم تُعدّ','red')}${metric('الزيادة بالوحدات',s.surplus,o.type==='open'?'لا يوجد مرجع للمقارنة':'زيادة عن الكمية المرجعية','green')}${metric('أصناف لم تُعدّ',s.unseen,nf(s.matched)+' أصناف مطابقة')}</div><section class="panel w-analysis"><div><h3>تغطية الأصناف المرجعية</h3><strong>${s.percent===null?'غير متاحة':nf(s.percent)+'%'}</strong><p>${s.percent===null?'الجرد الحر لا يحتوي على عدد أصناف مستهدف.':nf(s.done)+' من '+nf(s.total)+' أصناف مرجعية جرى عدّها.'}</p></div><div class="w-result-bars">${[['مطابق',s.matched,'matched'],['عجز',s.rows.filter(r=>r.diff!==null&&r.diff<0).length,'negative'],['زيادة',s.rows.filter(r=>r.diff!==null&&r.diff>0).length,'positive'],['لم يُعدّ',s.unseen,'unseen']].map(([label,n,tone])=>`<div><span>${label}</span><div><i class="${tone}" style="width:${s.rows.length?n/s.rows.length*100:0}%"></i></div><b>${nf(n)}</b></div>`).join('')}</div><p class="w-report-note">${s.pending?nf(s.pending)+' تكرار لم يُعالج؛ قد يؤثر في النتيجة.':'لا توجد تكرارات معلقة في هذه العملية.'}<br>هذه أعداد أصناف؛ «لم يُعدّ» قد يدخل أيضًا ضمن العجز. لا تمثل الأعمدة تقسيمًا حصريًا.</p></section>`:''}<div class="w-tabs" role="tablist" aria-label="نوع التقرير">${[['variance','الأصناف والفروقات'],['employees','أداء الموظفين'],['history','سجل الإدخالات والتعديلات']].map(([k,v])=>`<button role="tab" aria-selected="${reportKind===k}" class="${reportKind===k?'active':''}" onclick="changeReportKind('${k}')">${v}</button>`).join('')}</div><section class="panel">${reportKind==='variance'?`<div class="w-report-filters"><input aria-label="بحث التقرير" placeholder="ابحث باسم الصنف أو الباركود…" value="${esc(reportQuery)}" oninput="reportQuery=this.value;reportPage=1;refreshReportResults()"><select aria-label="حالة الصنف" onchange="reportState=this.value;reportPage=1;refreshReportResults()">${[['all','كل الأصناف'],['shortage','العجز'],['surplus','الزيادة'],['matched','المطابق'],['unseen','لم يُعدّ'],['unexpected','بلا مرجع']].map(([k,v])=>`<option value="${k}" ${k===reportState?'selected':''}>${v}</option>`).join('')}</select></div>`:''}<div id="wReportResults">${reportBody()}</div></section><p class="muted">التصدير يتبع التبويب الحالي. تقرير الأصناف يتبع البحث والفلتر ويشمل جميع صفحات النتائج.</p>`};
function reportExportRows(){const o=op(selected);if(!o||!visibleOps().includes(o))return [];if(reportKind==='employees')return [['الموظف','الإدخالات','الأصناف المختلفة','الوحدات','آخر إدخال'],...employeeRows([o]).map(r=>[r.name,r.records,r.items,r.units,r.last||''])];if(reportKind==='history')return [['الباركود','الموظف','الموقع','الكمية','مستبعد','المصدر','الوقت','الملاحظات'],...db.logs.filter(l=>l.op===o.id).map(l=>[l.barcode,l.user==='company'?'حساب الشركة':user(l.user),l.location,l.qty,l.excluded?'نعم':'لا',l.source||'عدّ',l.time,l.note])];return [['الباركود','الصنف','المرجع','المعدود','الفرق','الحالة'],...reportData().map(r=>[r.barcode,r.name,r.expected??'',r.count,r.diff??'',rowStatus(r)[0]])]}
function exportWorkspaceReport(){const rows=reportExportRows();if(!rows.length)return toast('لا توجد عملية للتصدير');download('\ufeff'+rows.map(r=>r.map(safeCell).join(',')).join('\r\n'),selected+'-'+reportKind+'.csv','text/csv;charset=utf-8')}
function printWorkspaceReport(){if(!canReview()||!needFeature('pdf')||!op(selected))return;const el=$('#wReportPrint');if(el)el.remove();const div=document.createElement('section');div.id='wReportPrint';const rows=reportExportRows();div.innerHTML=reportHeading()+`<h3>${{variance:'الأصناف والفروقات',employees:'أداء الموظفين',history:'سجل الإدخالات والتعديلات'}[reportKind]}</h3><table><thead><tr>${rows[0].map(c=>'<th>'+esc(c)+'</th>').join('')}</tr></thead><tbody>${rows.slice(1).map(r=>'<tr>'+r.map(c=>'<td>'+esc(c)+'</td>').join('')+'</tr>').join('')}</tbody></table>`;document.body.append(div);window.print()}
function wordWorkspaceReport(){if(!canReview()||!needFeature('word')||!op(selected))return;if(reportKind!=='variance')return toast('Word متاح لتقرير الأصناف والفروقات. استخدم CSV أو PDF لهذا التبويب.');const blob=ROFiles.docx(db.companyProfile.name,op(selected),reportData(),hasFeature('branding')?db.companyProfile.logo:null),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=selected+'-variance.docx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
const workspaceLanding=landing;landing=function(){return workspaceLanding().replace('<section class="blue-hero">',`<div class="w-demo-entry"><span>استكشف RO ببيانات تجريبية</span><button onclick="demoScreen('company')">لوحة الشركة</button><button onclick="demoScreen('employee')">شاشة الموظف</button><button onclick="demoScreen('platform')">إدارة المنصة</button></div><section class="blue-hero">`)};
const wHome=employeeHome;employeeHome=function(){return wHome().replace('<h1>عمليات الجرد المسندة لك</h1>',`<div class="w-employee-intro"><span>مرحبًا ${esc(user(activeUser()))}</span><h1>جاهز نبدأ الجرد؟</h1><p>افتح عمليتك. امسح الصنف. سجّل الكمية.</p></div>`)};
const wScan=scanPage;scanPage=function(){let html=wScan();if(db.role!=='employee')return html;const o=op(selected),n=o?logs(o.id).filter(l=>l.user===activeUser()).length:0;return html.replace('<section class="panel scan counter-panel">',`<div class="w-scan-steps"><span class="active">1 · امسح الباركود</span><span>2 · أدخل الكمية</span><span>3 · احفظ</span></div><div class="w-scan-session" id="wScanSession">سجلت ${nf(n)} إدخالات في هذه العملية</div><section class="panel scan counter-panel">`).replace('<label class="field">رقم الباركود','<label class="field w-barcode-field">رقم الباركود').replace('<label class="field">ملاحظات <small>اختياري</small>','<label class="field w-note-field">ملاحظات <small>اختياري</small>')};
const wAttach=attachScan;attachScan=function(){wAttach();const form=$('#scanForm');if(!form||db.role!=='employee')return;const location=form.elements.location.closest('label'),note=form.elements.note.closest('label'),details=document.createElement('details');details.className='w-scan-details';const summary=document.createElement('summary');summary.textContent='الموقع والملاحظات · '+form.elements.location.value;const locationInput=form.elements.location;details.append(summary,location,note);form.querySelector('.save-count').before(details);locationInput.addEventListener('input',()=>summary.textContent='الموقع والملاحظات · '+locationInput.value);const prev=form.onsubmit;form.onsubmit=e=>{const before=db.logs.length;prev(e);if(db.logs.length>before){$('#wScanSession').textContent='تم حفظ الصنف ✓ · سجلت '+nf(logs(selected).filter(l=>l.user===activeUser()).length)+' إدخالات';form.elements.barcode.blur();form.elements.qty.blur();form.dataset.stage='scan';}};form.addEventListener('ro:barcode',()=>form.dataset.stage='quantity');form.elements.barcode.addEventListener('input',()=>form.dataset.stage=form.elements.barcode.value?'quantity':'scan')};
const wSettings=settings;settings=function(){return wSettings().replace('GitHub الحالي: بانتظار رابط المستودع','GitHub: 76-beep/jard')};
const wRender=render;render=function(){wRender();if(db.role==='employee'&&page==='scan'&&!navigator.mediaDevices?.getUserMedia&&$('#cameraStatus'))$('#cameraStatus').textContent='الكاميرا تتطلب رابطًا آمنًا وصلاحية المتصفح. استخدم رابط RO المنشور أو أدخل الباركود يدويًا.';if(document.body.classList.contains('public-flow'))return;const nav=$('#nav');if(nav&&db.role!=='employee'){nav.querySelectorAll('button').forEach(b=>{const em=b.querySelector('em');if(em){const help={dashboard:'الملخص والتنبيهات',operations:'الإنشاء ومتابعة التنفيذ',scan:'تسجيل الكميات',review:'حل التكرارات',team:'الأعضاء والفروع',reports:'النتائج والتصدير',plans:'الرصيد والاشتراك',settings:'الأدوار وحالة الربط',platform:'الشركات والباقات والطلبات'};const p=(b.getAttribute('onclick')||'').match(/go\('([^']+)'\)/)?.[1];if(help[p])em.insertAdjacentHTML('beforeend','<small>'+help[p]+'</small>')}});if(!$('#wRoleNav'))nav.insertAdjacentHTML('beforebegin',`<div class="w-nav-label" id="wRoleNav">${canManage()?'مساحة الشركة':'مساحة مسؤول الجرد'}</div>`)}if(page==='reports'&&reportKind!=='variance'){document.querySelectorAll('.heading button').forEach(b=>{if(b.textContent.includes('Word')){b.disabled=true;b.title='Word متاح لتقرير الأصناف والفروقات'}})}};
render();
